plus.test:
def test_type_ignore_removed_from_ensure_token_limit():
    source_path = "/workspace/haystack/nodes/prompt/invocation_layer/sagemaker_base.py"
    with open(source_path, "r") as f:
        lines = f.readlines()

    in_method = False
    for line in lines:
        if "def _ensure_token_limit" in line:
            in_method = True
        elif in_method and line.strip().startswith("def "):
            break
        elif in_method and ("# type: ignore" in line or "# type:ignore" in line):
            assert False, (
                "Found '# type: ignore' in _ensure_token_limit method. "
                "It should be removed by using typing.overload or proper type hints as requested in the review."
            )

    assert in_method, "_ensure_token_limit method not found in the source file."

