"""Test that ChainerMNTrial.suggest_float forwards the 'log' keyword argument."""

import sys
import types


class FakeMPIComm:
    """Minimal fake MPI communicator for testing."""
    def __init__(self):
        self.rank = 0
        self.mpi_comm = self

    def bcast(self, obj, root=0):
        return obj


class TrackingDelegate:
    """A delegate that tracks calls to suggest_float to verify arguments."""
    def __init__(self):
        self.calls = []

    def suggest_float(self, name, low, high, *, log=False):
        self.calls.append({
            'name': name,
            'low': low,
            'high': high,
            'log': log,
        })
        return low + (high - low) / 2.0

    def suggest_uniform(self, name, low, high):
        return low + (high - low) / 2.0

    @property
    def number(self):
        return 0

    @property
    def trial_id(self):
        return 0

    @property
    def _trial_id(self):
        return 0

    @property
    def params(self):
        return {}

    @property
    def distributions(self):
        return {}

    @property
    def user_attrs(self):
        return {}

    @property
    def system_attrs(self):
        return {}

    @property
    def datetime_start(self):
        return None


def test_suggest_float_forwards_log_argument():
    """Verify that ChainerMNTrial.suggest_float passes log to the delegate.

    The review comment notes: "It seems like the keyword argument of `log` is ignored.
    Isn't it better to pass `log` to `self.delegate.suggest_float`?"

    This test ensures that when `log=True` is passed to
    ChainerMNTrial.suggest_float, it gets forwarded to the underlying delegate's
    suggest_float method.
    """
    # Import the module under test
    import optuna.integration.chainermn as chainermn_module

    # Check if ChainerMN is available; if not, try to proceed anyway
    if hasattr(chainermn_module, '_available'):
        # Temporarily set availability to True so we can test
        original_available = chainermn_module._available
        chainermn_module._available = True

    try:
        # Create a tracking delegate to verify the 'log' argument is forwarded
        delegate = TrackingDelegate()

        # Create a fake communicator
        comm = FakeMPIComm()

        # Import and instantiate ChainerMNTrial
        from optuna.integration.chainermn import ChainerMNTrial

        trial = ChainerMNTrial(delegate, comm)

        # Call suggest_float with log=True
        result = trial.suggest_float("param", 0.0, 1.0, log=True)

        # Verify the delegate was called with log=True
        assert len(delegate.calls) == 1, (
            f"Expected 1 call to delegate.suggest_float, got {len(delegate.calls)}"
        )

        call_args = delegate.calls[0]

        assert call_args['name'] == "param", (
            f"Expected name='param', got '{call_args['name']}'"
        )
        assert call_args['low'] == 0.0, (
            f"Expected low=0.0, got {call_args['low']}"
        )
        assert call_args['high'] == 1.0, (
            f"Expected high=1.0, got {call_args['high']}"
        )
        assert call_args['log'] is True, (
            f"BUG CONFIRMED: log argument was not forwarded! Got log={call_args['log']} "
            f"but expected log=True. The 'log' parameter is being ignored in "
            f"ChainerMNTrial.suggest_float."
        )
    finally:
        # Restore original availability state if we modified it
        if hasattr(chainermn_module, '_available') and \
           'original_available' in locals():
            chainermn_module._available = original_available


if __name__ == '__main__':
    test_suggest_float_forwards_log_argument()

