"""Validation test for review comment 0: move enabled check to _async_run_script."""

import ast
import re


def test_enabled_check_moved_to_async_run_script():
    """Verify that script.enabled check was moved from async_run_with_trace to _async_run_script.

    Per the review comment, the enabled check should live in _async_run_script,
    not inline inside async_run_with_trace inside _async_step_parallel.
    """
    source = open("/workspace/homeassistant/helpers/script.py").read()

    # Parse into an AST to find _ScriptRun methods
    tree = ast.parse(source)

    found_enabled_in_run_script = False
    found_enabled_in_async_run_with_trace = False
    log_msg_contains_parallel = False
    docstring_has_enabled_note = False

    for node in ast.walk(tree):
        if isinstance(node, ast.AsyncFunctionDef) and node.name == "_async_run_script":
            method_src = ast.get_source_segment(source, node) or ""
            if "not script.enabled" in method_src:
                found_enabled_in_run_script = True

        if isinstance(node, ast.AsyncFunctionDef) and node.name == "_async_step_parallel":
            method_src = ast.get_source_segment(source, node) or ""
            # Check if the inner async_run_with_trace still has the old check
            # We look for the pattern inside _async_step_parallel
            inner_match = re.search(
                r"async def async_run_with_trace\([^)]*\)[^{]*\{(.*?)\n\s+results\s*=",
                method_src,
                re.DOTALL,
            )
            if inner_match:
                inner_body = inner_match.group(1)
                if "not script.enabled" in inner_body:
                    found_enabled_in_async_run_with_trace = True

    # Check log message does NOT contain "parallel"
    if 'self._log("Skipping disabled parallel script' in source:
        log_msg_contains_parallel = True

    # Check Script.__init__ docstring mentions enabled/non-top-level
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == "Script":
            for item in ast.walk(node):
                if isinstance(item, ast.FunctionDef) and item.name == "__init__":
                    init_src = ast.get_source_segment(source, item) or ""
                    if ("non-top-level" in init_src.lower() or "non_top_level" in init_src.lower()):
                        docstring_has_enabled_note = True
                    break

    assert found_enabled_in_run_script, (
        "_async_run_script should contain the 'script.enabled' guard."
    )
    assert not found_enabled_in_async_run_with_trace, (
        "The 'script.enabled' guard should NOT remain inside async_run_with_trace."
    )
    assert not log_msg_contains_parallel, (
        "Log message should not contain 'parallel'; it should read 'Skipping disabled script'."
    )
    assert docstring_has_enabled_note, (
        "Script.__init__ docstring should note that 'enabled' is only used for non-top-level scripts."
    )

