import pandas as pd


def test_drop_empty_list_non_unique_index():
    df = pd.DataFrame({"A": [1, 2, 3]}, index=["x", "x", "y"])

    try:
        result = df.drop([])
    except Exception as e:
        assert False, f"df.drop([]) raised an exception on non-unique indices: {e}"

    assert isinstance(result, pd.DataFrame), "df.drop([]) should return a DataFrame"
    assert result.equals(df), (
        f"df.drop([]) on a DataFrame with non-unique indices failed. "
        f"Expected {df.to_dict()}, got {result.to_dict()}"
    )

