describe('poloniex fetchOrderBook - conditional inversion fix', () => {
    test('order book asks should have prices from even indices (0, 2, 4...) and amounts from odd indices (1, 3, 5...)', () => {
        const exchange = new poloniex({
            'apiKey': 'test',
            'secret': 'test',
        });

        // Simulate the interleaved asks array from the API response
        // Format: [price0, amount0, price1, amount1, ...]
        // Even indices (0, 2, 4...) = prices
        // Odd indices (1, 3, 5...) = amounts
        const asks = ["23139.82", "0.317981", "23140", "0.191091"];
        const bids = ["23139.74", "0.432092", "23123.21", "0.000886"];

        const asksResult = [];
        const bidsResult = [];

        // Reproduce the fixed code logic from fetchOrderBook
        for (let i = 0; i < asks.length; i++) {
            if ((i % 2) === 0) {
                const price = exchange.safeNumber(asks, i);
                const amount = exchange.safeNumber(asks, exchange.sum(i, 1));
                asksResult.push([price, amount]);
            }
        }
        for (let i = 0; i < bids.length; i++) {
            if ((i % 2) === 0) {
                const price = exchange.safeNumber(bids, i);
                const amount = exchange.safeNumber(bids, exchange.sum(i, 1));
                bidsResult.push([price, amount]);
            }
        }

        // With the correct fix (i % 2 === 0), even indices are prices:
        // i=0: price=23139.82, amount=0.317981
        // i=2: price=23140, amount=0.191091

        // With the current buggy code (i % 2), odd indices are "prices":
        // i=1: price=0.317981, amount=23140  (WRONG - amount becomes price)
        // i=3: price=0.191091, amount=undefined (WRONG)

        // The first ask price should be the first element of the array (23139.82)
        // With the bug, it will be 0.317981 (the amount, not the price)
        expect(asksResult.length).toBeGreaterThan(0);

        const firstAskPrice = asksResult[0][0];
        const firstAskAmount = asksResult[0][1];

        // The price (23139.82) should be greater than the amount (0.317981)
        // With the bug, price=0.317981 and amount=23140, so price < amount (inverted)
        // With the fix, price=23139.82 and amount=0.317981, so price > amount (correct)
        expect(firstAskPrice).toBeGreaterThan(firstAskAmount);
    });
});

