'use strict';

const fs = require('fs');

describe('huobi fetchBalance - margin flag must be independent of spot type', () => {
    test('OLD broken code: if (spot) { if (isolated) ... } - cross/isolated only reachable when spot=true', () => {
        const source = fs.readFileSync('/workspace/js/huobi.js', 'utf8');

        // Extract the fetchBalance method body
        const fetchBalanceStart = source.indexOf('async fetchBalance (params = {})');
        const fetchBalanceEnd = source.indexOf('\n    async fetchOrder', fetchBalanceStart);
        const fetchBalanceBody = source.substring(fetchBalanceStart, fetchBalanceEnd);

        // The OLD (broken) code structure was:
        //   if (spot) {
        //     if (isolated) { ... }
        //     else if (cross) { ... }
        //     else { spot account }
        //   }
        // This means isolated/cross were INSIDE the spot check, so without type='spot', they were unreachable

        // The FIX requires: const margin = (type === 'margin') || cross || isolated
        // followed by: if (spot || margin) { if (margin) { ... } else { ... } }

        // Assert the fix is present: margin must be defined BEFORE the if(spot...) block
        // and must include cross || isolated
        const marginVarIndex = fetchBalanceBody.indexOf('const margin =');
        const spotIfIndex = fetchBalanceBody.indexOf('if (spot');

        // The margin variable must exist
        expect(marginVarIndex).toBeGreaterThan(-1);

        // The margin variable must be defined BEFORE the if(spot...) block
        expect(marginVarIndex).toBeLessThan(spotIfIndex);

        // The margin variable definition must include cross || isolated (not just type === 'margin')
        const marginVarLine = fetchBalanceBody.substring(marginVarIndex, fetchBalanceBody.indexOf('\n', marginVarIndex));

        // This assertion will FAIL on old code because old code has:
        // `if (spot) { if (isolated)` instead of `const margin = ... || cross || isolated`
        expect(marginVarLine).toMatch(/cross\s*\|\|\s*isolated/);
    });

    test('OLD broken code: isolated/cross endpoints NESTED inside spot check - must be at same level via margin flag', () => {
        const source = fs.readFileSync('/workspace/js/huobi.js', 'utf8');

        const fetchBalanceStart = source.indexOf('async fetchBalance (params = {})');
        const fetchBalanceEnd = source.indexOf('\n    async fetchOrder', fetchBalanceStart);
        const fetchBalanceBody = source.substring(fetchBalanceStart, fetchBalanceEnd);

        // OLD broken code had `if (spot) {` directly containing `if (isolated)` / `else if (cross)`
        // which meant marginMode alone (without type=spot) could not reach those endpoints
        //
        // NEW correct code: outer condition is `if (spot || margin)` where margin = cross || isolated
        // This allows marginMode:isolated/cross to work without needing type:spot explicitly

        // The OLD broken pattern: "if (spot) {" followed immediately (within ~5 lines) by "if (isolated)"
        // Check that there is NO pattern of: if (spot) { \n if (isolated)
        // (the old code that caused the bug)

        const oldBrokenPattern = /if\s*\(\s*spot\s*\)\s*\{[^}]{0,200}if\s*\(\s*isolated\s*\)/s;

        // On OLD code, this pattern WOULD match (causing test to fail as expected)
        // On NEW fixed code, this pattern should NOT match
        const matchesOldPattern = oldBrokenPattern.test(fetchBalanceBody);

        expect(matchesOldPattern).toBe(false,
            'OLD broken code had isolated/cross margin endpoints nested inside if(spot) block. ' +
            'Fix requires: const margin = (type==="margin") || cross || isolated, and if(spot || margin) at outer level. ' +
            'When marginMode=isolated/cross is set without type=spot, it should still reach margin endpoints.');
    });
});

