describe('bitget fetchOHLCV - retrievableDaysMap should be in options', () => {
  test('retrievableDaysMapForSpot should be accessible via exchange options, not hardcoded', () => {
    // Read the source file to verify structure
    const fs = require('fs');
    const source = fs.readFileSync('/workspace/ts/src/bitget.ts', 'utf8');

    // The review comment says the retrievable days map should be stored in options
    // Currently it's hardcoded as a local const inside fetchOHLCV
    // After fix, it should be in the options object in describe()

    // Find the describe() method's options block start and end
    const optionsRegionStart = source.indexOf("'options':");
    // The options block ends at the 'precisionMode' key which is BEFORE 'options' in file;
    // instead find the closing of the options block by locating fetchOHLCV in it
    const fetchOHLCVInOptions = source.indexOf("'fetchOHLCV':", optionsRegionStart);
    // Use a generous window that includes the fetchOHLCV options entry
    const optionsRegion = source.substring(optionsRegionStart, fetchOHLCVInOptions + 2000);

    // The key check: retrievableDaysMapForSpot should NOT be a local const inside fetchOHLCV
    // It should be in options

    // Current code has: const retrievableDaysMapForSpot = { '1m': 30, ... } inside fetchOHLCV
    // Fixed code should have it in options

    // Check that it's in options (the fix should add it there)
    const isInOptions = optionsRegion.includes('retrievableDaysMapForSpot') ||
                        optionsRegion.includes('retrievableDays') ||
                        (optionsRegion.includes("'1h': 83") || optionsRegion.includes('"1h": 83'));

    // The test FAILS on current code because the map is a local const, not in options
    expect(isInOptions).toBe(true);
  });

