    const optionsStart = source.indexOf("'options':");
    const fetchOHLCVMethodStart = source.indexOf('async fetchOHLCV (');
    const optionsRegion = source.substring(optionsStart, fetchOHLCVMethodStart);

    // The reviewer wants this stored in options so users can override
    // After fix, something like options.fetchOHLCV.retrievableDaysMapForSpot should exist
    const hasRetrievableDaysInOptions =
      optionsRegion.includes('retrievableDaysMapForSpot') ||
      optionsRegion.includes('retrievableDays');

    expect(hasRetrievableDaysInOptions).toBe(true);
  });
});

