/**
 * Test for update_scheduled_message sorting behavior.
 * 
 * Review comment: sorting should happen unconditionally in update_scheduled_message,
 * not only when scheduled_delivery_timestamp changes.
 * 
 * Current code only sorts when timestamp changes. After fix, it should always sort.
 */

// We test by reading the source file and checking the structural change
// since mocking all the imports for this module is complex.
// The key behavioral check: sorting should NOT be conditional on timestamp change.

const fs = require('fs');

describe('update_scheduled_message unconditional sorting', () => {
    test('should sort scheduled_messages_data unconditionally, not only when timestamp changes', () => {
        const source = fs.readFileSync('/workspace/web/src/scheduled_messages.js', 'utf8');

        // Find the update_scheduled_message function body
        const updateFuncMatch = source.match(/export function update_scheduled_message[\s\S]*?^}/m);

        // The current (buggy) code has a conditional flag before sorting.
        // After the fix, the sort should be called unconditionally.
        // The conditional pattern checks if timestamp changed before deciding to sort.

        // Current code pattern: checks timestamp difference, sets flag, sorts conditionally
        const hasConditionalTimestampSort = /scheduled_delivery_timestamp[\s\S]{0,200}needs_to_sorted|needs_resorting/.test(source);

        // Also check for the if-block around sort_scheduled_messages_data inside update function
        // Current buggy pattern: `if (needs_to_sorted) { sort_scheduled_messages_data(); }`
        const hasSortInsideConditional = /if\s*\(\s*(needs_to_sorted|needs_resorting)\s*\)[\s\S]{0,100}sort_scheduled_messages_data/.test(source);

        // The fix should eliminate BOTH of these patterns
        expect(hasConditionalTimestampSort).toBe(false);
        expect(hasSortInsideConditional).toBe(false);

        // And the sort should still exist (just unconditionally)
        // Find if update_scheduled_message contains sort_scheduled_messages_data
        // by checking the source has it somewhere after the function definition
        expect(source).toMatch(/sort_scheduled_messages_data/);
    });
});

